// ── Road Network Loader ───────────────────────────────────
// Loads hand-drawn road network from tract4207_road_network.json
// instead of fetching live OSM data from Overpass API.
// The JSON file is generated by the road-editor.html tool.
//
// Exports the same public API as before (preloadOsmRoads,
// getOsmStreetGrid, isOsmReady) so no callers need to change.

import { StreetGrid } from '../constants/coordinates';
import roadNetworkJson from '../data/tract4207_road_network.json';

// ── Module-level cache ────────────────────────────────────

let cachedGrid: StreetGrid | null = null;

// ── Public API ────────────────────────────────────────────

/**
 * Load the hand-drawn road network (synchronous import, non-blocking).
 * Signature kept compatible with the old OSM preloader.
 */
export function preloadOsmRoads(
  _width?: number,
  _height?: number,
  _padding?: number,
  _outlineCoords?: unknown,
  _bbox?: unknown,
): void {
  if (cachedGrid) return;

  try {
    const raw = roadNetworkJson as any;
    const grid = raw.grid as StreetGrid;
    if (grid && grid.nodes && Array.isArray(grid.nodes) && grid.edges && Array.isArray(grid.edges)) {
      cachedGrid = grid;

      // Compute connected components for diagnostics
      const adj = new Map<string, string[]>();
      for (const n of grid.nodes) adj.set(n.id, []);
      for (const e of grid.edges) {
        adj.get(e.from)?.push(e.to);
        adj.get(e.to)?.push(e.from);
      }
      const visited = new Set<string>();
      const comps: number[] = [];
      for (const n of grid.nodes) {
        if (visited.has(n.id)) continue;
        let size = 0;
        const q = [n.id]; visited.add(n.id);
        while (q.length) { const c = q.shift()!; size++; for (const nb of (adj.get(c) || [])) { if (!visited.has(nb)) { visited.add(nb); q.push(nb); } } }
        comps.push(size);
      }
      console.log(
        `[ROAD] Loaded hand-drawn road network: ${grid.nodes.length} nodes, ${grid.edges.length} edges, ${comps.length} connected component(s) [${comps.join(', ')} nodes each].`
      );
    } else {
      console.warn('[ROAD] JSON missing grid.nodes/grid.edges — falling back to synthetic grid.');
    }
  } catch (err) {
    console.warn('[ROAD] Failed to load road network JSON:', err);
  }
}

/** Returns the road graph if loaded, otherwise null. */
export function getOsmStreetGrid(): StreetGrid | null {
  return cachedGrid;
}

/** Returns true once road data has been loaded. */
export function isOsmReady(): boolean {
  return cachedGrid !== null;
}
